package com.yigongbao.module.backup.restore;
import org.junit.jupiter.api.Test; import java.util.List; import static org.assertj.core.api.Assertions.*;
class InMemoryRestoreSessionServiceTest { @Test void commitIsIdempotentAndAbortCannotFollowCommit(){var s=new InMemoryRestoreSessionService();var p=s.prepare(1L,"r1","d1");var a=new RestoreSessionService.UploadedAsset("a","k","h",1);var c=s.commit(p.id(),List.of(a));assertThat(s.commit(p.id(),List.of(a)).status()).isEqualTo("COMMITTED");assertThatThrownBy(()->s.abort(p.id(),"x")).isInstanceOf(IllegalStateException.class);assertThat(c.uploaded()).containsExactly(a);} @Test void rejectsDuplicateEvidence(){var s=new InMemoryRestoreSessionService();var p=s.prepare(1L,"r","d");var a=new RestoreSessionService.UploadedAsset("a","k","h",1);assertThatThrownBy(()->s.commit(p.id(),List.of(a,a))).isInstanceOf(IllegalArgumentException.class);} }
